# Day of Judgment (FDN): "Destroy all creatures."
# M20 Planar Cleansing's verified DESTROY over an ALL selector (QUnbounded), filter TYPE_EQ
# Creature (Pestilent Haze's "all creatures"), any controller.
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=A(Verb.DESTROY, {
            'target': Selector(
                count=QUnbounded(),
                mode=SelectorMode.ALL,
                filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
